def shortestSameDegree(nums):
    first = {}
    last = {}
    cnt = {}
    for i, x in enumerate(nums):
        if x not in first:
            first[x] = i
        last[x] = i
        cnt[x] = cnt.get(x, 0) + 1
    deg = max(cnt.values())
    return min(last[x] - first[x] + 1 for x in cnt if cnt[x] == deg)
